namespace{juce::Component*findAIPanel(MainComponent&o){for(int i=0;i<o.getNumChildComponents();++i){auto*c=o.getChildComponent(i);if(!c)continue;for(int j=0;j<c->getNumChildComponents();++j)if(auto*l=dynamic_cast<juce::Label*>(c->getChildComponent(j)))if(l->getText()=="LIBERTY AI MUSIC")return c;}return nullptr;}juce::Component*findSongEnergy(juce::Component&p){for(int i=0;i<p.getNumChildComponents();++i){auto*c=p.getChildComponent(i);if(!c)continue;for(int j=0;j<c->getNumChildComponents();++j)if(auto*l=dynamic_cast<juce::Label*>(c->getChildComponent(j)))if(l->getText()=="AI SONG ENERGY")return c;}return nullptr;}
class Composer final:public juce::Component{public:explicit Composer(MainComponent&o):owner(o){title.setText("AI COMPOSER 2",juce::dontSendNotification);title.setColour(juce::Label::textColourId,juce::Colour(0xffffc857));title.setFont(juce::Font(14,juce::Font::bold));addAndMakeVisible(title);style.addItemList({"POP","ROCK","METAL","FUNK","BLUES","AMBIENT","CINEMATIC","ELECTRONIC"},1);mood.addItemList({"DARK","BRIGHT","TENSE","EPIC","MELANCHOLIC","AGGRESSIVE","DREAMY"},1);progression.addItemList({"i-VI-III-VII","I-V-vi-IV","I-IV-V-I","ii-V-I","i-iv-V-i"},1);style.setSelectedId(3);mood.setSelectedId(1);progression.setSelectedId(1);for(auto*c:{&style,&mood,&progression})addAndMakeVisible(*c);setup(complexity,55);setup(energy,70);setup(human,18);generate.setButtonText("GENERATE SECTION");generate.setColour(juce::TextButton::buttonColourId,juce::Colour(0xff31465b));generate.onClick=[this]{make();};addAndMakeVisible(generate);status.setColour(juce::Label::textColourId,juce::Colour(0xff8edcff));addAndMakeVisible(status);setOpaque(true);}void paint(juce::Graphics&g)override{g.fillAll(juce::Colour(0xff121820));g.setColour(juce::Colour(0xff35414e));g.drawRoundedRectangle(getLocalBounds().toFloat(),5,1);g.setColour(juce::Colour(0xffaab5c0));g.setFont(10);g.drawText("COMPLEXITY",10,92,90,20,juce::Justification::centredLeft);g.drawText("ENERGY",10,122,90,20,juce::Justification::centredLeft);g.drawText("HUMAN FEEL",10,152,90,20,juce::Justification::centredLeft);}void resized()override{int w=getWidth();title.setBounds(10,5,w-20,22);style.setBounds(10,30,(w-30)/2,25);mood.setBounds(20+(w-30)/2,30,(w-30)/2,25);progression.setBounds(10,59,w-20,25);complexity.setBounds(102,90,w-112,24);energy.setBounds(102,120,w-112,24);human.setBounds(102,150,w-112,24);generate.setBounds(10,180,w-20,30);status.setBounds(10,211,w-20,22);}private:void setup(juce::Slider&s,double v){s.setRange(0,100,1);s.setValue(v);s.setTextBoxStyle(juce::Slider::TextBoxRight,false,44,18);addAndMakeVisible(s);}double secBar()const{return(60.0/juce::jmax(1.0,owner.tempoBpm))*owner.timeSignatureNumerator*(4.0/juce::jmax(1,owner.timeSignatureDenominator));}void make(){const int bars=8;auto bar=MidiEngine::ticksPerMeasure(owner.timeSignatureNumerator,owner.timeSignatureDenominator),q=MidiEngine::ticksPerQuarterNote;std::vector<MidiEngine::NoteEvent>out;std::mt19937 rng((unsigned)juce::Time::getMillisecondCounter());int roots[4]={0,8,3,10};if(progression.getSelectedId()==2){roots[0]=0;roots[1]=7;roots[2]=9;roots[3]=5;}else if(progression.getSelectedId()==3){roots[0]=0;roots[1]=5;roots[2]=7;roots[3]=0;}else if(progression.getSelectedId()==4){roots[0]=2;roots[1]=7;roots[2]=0;roots[3]=0;}else if(progression.getSelectedId()==5){roots[0]=0;roots[1]=5;roots[2]=7;roots[3]=0;}int base=48+(mood.getSelectedId()==2?12:0),vel=juce::jlimit(45,125,55+(int)energy.getValue()*7/10);for(int b=0;b<bars;++b){int r=roots[b%4];for(int k:{0,3,7}){MidiEngine::NoteEvent n;n.startTick=(std::int64_t)b*bar;n.lengthTicks=bar;n.pitch=(std::uint8_t)juce::jlimit(0,127,base+r+k);n.velocity=(std::uint8_t)vel;n.channel=1;out.push_back(n);}int steps=complexity.getValue()>70?8:(complexity.getValue()>35?4:2);for(int s=0;s<steps;++s){if((int)(rng()%100)>energy.getValue())continue;MidiEngine::NoteEvent n;n.startTick=(std::int64_t)b*bar+(std::int64_t)s*bar/steps;int feel=(int)human.getValue();n.startTick=juce::jmax<std::int64_t>(0,n.startTick+(feel?((int)(rng()%(feel+1))-feel/2):0));n.lengthTicks=juce::jmax<std::int64_t>(q/8,bar/steps*3/4);n.pitch=(std::uint8_t)juce::jlimit(0,127,base+12+r+(int)(rng()%8));n.velocity=(std::uint8_t)juce::jlimit(1,127,vel-15+(int)(rng()%20));n.channel=1;out.push_back(n);}}bool ok=commitLibertyAIGeneratedNotes(owner,out,true,juce::jmax(0.0,owner.midiClipStartSeconds),bars*secBar());status.setText(ok?"Section creee sur INSTRUMENT":"Creation impossible",juce::dontSendNotification);owner.repaint();}MainComponent&owner;juce::Label title,status;juce::ComboBox style,mood,progression;juce::Slider complexity,energy,human;juce::TextButton generate;};
class Controller:private juce::Timer{public:explicit Controller(MainComponent&o):owner(o){startTimerHz(2);}~Controller(){shutdown();}void shutdown(){stopTimer();if(box){box->setVisible(false);box.reset();}}private:void timerCallback()override{auto*p=findAIPanel(owner);if(!p||!p->isVisible()){if(box)box->setVisible(false);return;}if(!box){box=std::make_unique<Composer>(owner);p->addAndMakeVisible(*box);}const int h=240;int y=800;if(auto*song=findSongEnergy(*p))y=song->getBottom()+12;box->setBounds(20,y,juce::jmax(280,p->getWidth()-40),h);box->setVisible(y+h<=p->getHeight());}MainComponent&owner;std::unique_ptr<Composer>box;};std::map<MainComponent*,std::unique_ptr<Controller>>cs;class Boot:private juce::Timer{public:Boot(){startTimerHz(3);}~Boot(){shutdown();}void shutdown(){stopTimer();cs.clear();}private:void timerCallback()override{auto&d=juce::Desktop::getInstance();for(int i=0;i<d.getNumComponents();++i)if(auto*w=dynamic_cast<juce::DocumentWindow*>(d.getComponent(i)))if(auto*m=dynamic_cast<MainComponent*>(w->getContentComponent()))if(!cs.count(m))cs.emplace(m,std::make_unique<Controller>(*m));}}boot;}
